    ['network','asset','payTo'].every(key => op.expect[key] === workspace.manifest.signer[key]) &&
    BigInt(op.expect.maxAtomic) > 0n && BigInt(op.expect.maxAtomic) <= BigInt(workspaceOp.expect.maxAtomic) &&
