  try { await writePrivate(destination,raw); await syncDirectory(parent); }
  catch(error) { throw new InputError(error.code==='EEXIST'?'OPERATION_HANDOFF_DESTINATION_EXISTS':'OPERATION_HANDOFF_EXPORT_FAILED'); }
