export function handoffArguments(args, direction) {
  const keys=direction==='import'?['--file','--dir','--accept']:['--config','--discovery','--out'];
  need(args.length===keys.length*2,'OPERATION_HANDOFF_FLAGS_REQUIRED');
  const flags=new Map();
