JS = r'''

window.customerExports=(()=>{
  const x={review:null,reviewPending:false,active:null,selected:null,history:null,before:null,pages:[],reviewLoad:0,detailLoad:0,historyLoad:0,workspace:null,restored:false};
  const options=['full-export-label','full-export-timeout','full-export-max-rows','full-export-max-bytes','full-export-safe-csv'];
  const pretty=value=>JSON.stringify(value,null,2);
  const key=suffix=>'sf-query-export:'+s.data.workspace_id+':'+suffix;
  const title=job=>job.request?.label||job.label||job.request?.name||'Query export';
  const units=value=>Number.isFinite(value)?new Intl.NumberFormat().format(value):'—';
  const bytes=value=>Number.isFinite(value)?units(value)+' bytes':'—';
  const queryLabel=job=>(job.request?.name||'Analysis')+' · '+stamp(job.finished_at)+' · '+short(job.id);
  function selectedFormats(){return [...document.querySelectorAll('[name="full-export-format"]:checked')].map(input=>input.value);}
  function optionValues(){return {label:$('full-export-label').value,timeout:$('full-export-timeout').value,max_rows:$('full-export-max-rows').value,max_output_bytes:$('full-export-max-bytes').value,spreadsheet_safe:$('full-export-safe-csv').checked,formats:selectedFormats()};}
  function rememberOptions(){if(s.data)try{localStorage.setItem(key('options'),JSON.stringify(optionValues()));}catch{}controls();}
  function restoreOptions(){
    let value;try{value=JSON.parse(localStorage.getItem(key('options')));}catch{}
    if(!value||typeof value!=='object')return;
    for(const [field,name]of [['full-export-label','label'],['full-export-timeout','timeout'],['full-export-max-rows','max_rows'],['full-export-max-bytes','max_output_bytes']])if(typeof value[name]==='string')$(field).value=value[name];
    if(typeof value.spreadsheet_safe==='boolean')$('full-export-safe-csv').checked=value.spreadsheet_safe;
    if(Array.isArray(value.formats))for(const input of document.querySelectorAll('[name="full-export-format"]'))input.checked=value.formats.includes(input.value);
  }
  function queryOptions(){
    const queries=new Map((s.data?.jobs||[]).filter(job=>job.kind==='query'&&job.status==='COMPLETE').map(job=>[job.id,job]));
    for(const job of [s.result,x.review])if(job?.kind==='query'&&job.status==='COMPLETE')queries.set(job.id,job);
    const select=$('full-export-query');select.replaceChildren();const blank=node('option','Choose a completed analysis');blank.value='';select.append(blank);
    for(const job of queries.values()){const option=node('option',queryLabel(job));option.value=job.id;select.append(option);}
    select.value=x.review?.id||'';
  }
  function renderReview(){
    const job=x.review;$('full-export-review').hidden=!job;
    if(!job){controls();return;}
    const box=$('full-export-review-facts');box.replaceChildren();
    fact(box,'Analysis',job.request.name||'Retained SQL analysis');fact(box,'Review',job.id);fact(box,'Completed',stamp(job.finished_at));
    fact(box,'Preview rows',job.result.total_rows??job.result.rows?.length??0);fact(box,'Preview limited',job.result.truncated?'Yes':'No');
    $('full-export-sql').textContent=job.request.sql;
    $('full-export-parameters').textContent=job.request.parameters_text;
    $('full-export-review-context').textContent=pretty({query_id:job.id,result_sha256:job.result.result_sha256,reviewed_views:job.result.views,read_tables:job.result.read_tables,source_versions:job.result.source_versions});
    controls();
  }
  async function review(query){
    const sequence=++x.reviewLoad;let job;
    try{job=typeof query==='string'?await api('/api/jobs/'+encodeURIComponent(query)):query;}
    catch(error){if(sequence===x.reviewLoad)queryOptions();throw error;}
    if(sequence!==x.reviewLoad)return;
    if(job?.kind!=='query'||job.status!=='COMPLETE'||!job.result?.result_sha256)throw Error('Choose a completed analysis review before exporting.');
    x.review=job;queryOptions();renderReview();tab('exports');
    message('Query review selected. Choose output files and export limits.');
  }
  async function reviewEditor(){
    x.reviewPending=true;
    try{await start('query',{...editorValue(),expected_views:s.data.views});}
    catch(error){x.reviewPending=false;throw error;}
  }
  async function queryReady(job){if(x.reviewPending){x.reviewPending=false;await review(job);}else queryOptions();}
  function integer(field,{optional=false,max=Number.MAX_SAFE_INTEGER}={}){
    const raw=$(field).value.trim();if(optional&&!raw)return null;
    const value=Number(raw);if(!raw||!Number.isSafeInteger(value)||value<1||value>max)throw Error($(field).closest('label').childNodes[0].textContent.trim()+' must be a positive whole number'+(max===86400?' through 86400.':'.'));
    return value;
  }
  async function begin(){
    const job=x.review;if(!job)throw Error('Choose a completed analysis review.');
    const formats=selectedFormats();if(!formats.length)throw Error('Choose at least one output file format.');
    rememberOptions();
    await start('query-export',{query_id:job.id,result_sha256:job.result.result_sha256,label:$('full-export-label').value.trim(),formats,timeout:integer('full-export-timeout',{max:86400}),max_rows:integer('full-export-max-rows',{optional:true}),max_output_bytes:integer('full-export-max-bytes',{optional:true}),spreadsheet_safe:$('full-export-safe-csv').checked});
    tab('exports');
  }
  function controls(){
    const unavailable=s.busy||!s.data;
    for(const id of ['full-export-choose','full-export-query','full-export-use-result','full-export-history-refresh','full-export-history-prev','full-export-history-next','full-export-reuse','full-export-run','full-export-cancel','full-export-from-result','full-export-review-editor'])$(id).disabled=unavailable;
    for(const input of document.querySelectorAll('#full-export-form input'))input.disabled=unavailable;
    $('full-export-run').disabled||=Boolean(s.active)||!x.review||!selectedFormats().length;
    $('full-export-review-editor').disabled||=Boolean(s.active);
    $('full-export-from-result').disabled||=s.result?.status!=='COMPLETE';
    $('full-export-use-result').disabled||=s.result?.status!=='COMPLETE';
    $('full-export-history-prev').disabled||=!x.pages.length;
    $('full-export-history-next').disabled||=x.history?.next_before==null;
    $('full-export-reuse').disabled||=!x.selected?.request?.query_id;
    $('full-export-cancel').disabled||=x.active?.status!=='RUNNING'||Boolean(x.active?.progress?.cancel_requested);
    for(const button of document.querySelectorAll('#full-export-files button,#full-export-history button'))button.disabled=unavailable;
  }
  function renderActive(){
    const job=x.active;$('full-export-progress').hidden=job?.status!=='RUNNING';
    if(!job)return;
    $('full-export-progress-name').textContent=title(job)+' · '+job.id;
    $('full-export-progress-title').textContent=job.progress?.cancel_requested?'Cancelling export':'Export in progress';
    const box=$('full-export-progress-facts');box.replaceChildren();
    fact(box,'Rows written',units(job.progress?.rows??0));fact(box,'Output written',bytes(job.progress?.outputBytes??0));fact(box,'Updated',stamp(job.progress?.updated_at||job.created_at));
    $('full-export-progress-note').textContent=job.progress?.cancel_requested?'Cancellation is recorded. The query will stop at its next cancellation check.':'The query reports rows and output bytes as it writes. You can continue viewing saved data while it runs.';
    $('full-export-progress-bar').removeAttribute('value');controls();
  }
  function progress(job){
    if(job.kind!=='query-export')return;
    if(job.status==='RUNNING')x.active=job;else if(x.active?.id===job.id)x.active=null;
    if(x.selected?.id===job.id||!x.selected&&s.focusJob===job.id){x.selected=job;renderDetail();}
    renderActive();
    const row=document.querySelector('#full-export-history tr[data-export="'+job.id+'"]');
    if(row){row.children[2].textContent=job.status+(job.progress?.cancel_requested?' · cancellation requested':'');row.children[3].textContent=units(job.result?.manifest?.rowCount??job.progress?.rows);row.children[4].textContent=bytes(job.progress?.outputBytes);}
  }
  function settled(job){if(job.kind==='query'&&job.status!=='COMPLETE')x.reviewPending=false;progress(job);}
  async function cancel(){
    const job=x.active;if(job?.status!=='RUNNING')return;
    const value=await api('/api/query-exports/'+job.id+'/cancel',{});progress(value);
    message(value.status==='RUNNING'?'Cancellation requested for the current export.':'Export '+value.status.toLowerCase()+'.');
    if(value.status!=='RUNNING')await completed(value);
  }
  async function history(before=x.before,pages=x.pages){
    const sequence=++x.historyLoad,value=await api('/api/query-exports'+(before==null?'':'?before='+encodeURIComponent(before)));
    if(sequence!==x.historyLoad)return;
    x.history=value;x.before=before;x.pages=pages;
    const body=$('full-export-history');body.replaceChildren();
    for(const job of value.items){
      const row=node('tr');row.dataset.export=job.id;row.classList.toggle('selected',job.id===x.selected?.id);
      cell(row,stamp(job.created_at));const name=cell(row,job.label||short(job.id));name.title=job.id;
      cell(row,job.status+(job.progress?.cancel_requested&&job.status==='RUNNING'?' · cancellation requested':'')+(job.error?' · '+job.error:''));
      cell(row,units(job.row_count??job.progress?.rows));cell(row,bytes(job.output_bytes??job.progress?.outputBytes));cell(row).append(button('Open',()=>open(job.id)));body.append(row);
    }
    if(!value.items.length)empty(body,6,'No exports on this page. Complete a query review and choose its output files above.');
    $('full-export-history-page').textContent='History page '+(x.pages.length+1)+' · '+value.items.length+' exports shown · newest first';controls();
  }
  function renderDetail(){
    const job=x.selected;$('full-export-detail').hidden=!job;if(!job)return;
    $('full-export-detail-label').textContent=title(job)+' · '+job.id;
    const box=$('full-export-detail-facts');box.replaceChildren();
    fact(box,'Status',job.status);fact(box,'Started',stamp(job.created_at));fact(box,'Finished',stamp(job.finished_at));fact(box,'Query review',job.request.query_id);
    fact(box,'Selected formats',job.request.formats.join(', '));fact(box,'Execution timeout',job.request.timeout+' seconds');
    fact(box,'Maximum rows',job.request.max_rows==null?'No additional limit':units(job.request.max_rows));fact(box,'Maximum output',job.request.max_output_bytes==null?'No additional limit':bytes(job.request.max_output_bytes));
    const result=job.status==='COMPLETE'?job.result:null;$('full-export-complete').hidden=!result;
    $('full-export-outcome').textContent=result?'Complete query · '+units(result.manifest.rowCount)+' rows · '+units(result.files.length)+' retained files. The executed SQL and original source scope are recorded below.':job.status==='RUNNING'?job.progress?.cancel_requested?'Cancellation requested. Waiting for the query to stop.':'Writing the complete query result. Progress appears above.':job.status==='CANCELLED'?'Export cancelled. Its original query review remains available for another export.':job.status==='INTERRUPTED'?'The workspace stopped during this export. Reopen its query review to start another export.':job.error||'This export did not complete.';
    if(result){
      fact(box,'Rows',units(result.manifest.rowCount));fact(box,'Retained directory',result.directory);fact(box,'Manifest SHA-256',result.manifest_sha256);
      const files=$('full-export-files');files.replaceChildren();
      for(const file of result.files){const row=node('tr');cell(row,file.name,'code');cell(row,units(file.bytes));cell(row,file.sha256,'code');cell(row).append(button('Download',()=>downloadFile(job,file)));files.append(row);}
      $('full-export-result-sql').textContent=result.manifest.binding.sql;
      $('full-export-result-parameters').textContent=result.source_query.parameters_text;
      $('full-export-result-context').textContent=pretty({source_query:result.source_query,queryComplete:result.manifest.queryComplete,reviewed_views:result.manifest.binding.views,read_tables:result.manifest.binding.readTables,source_versions:result.manifest.binding.sourceVersions});
      $('full-export-manifest').textContent=result.manifest_text;
    }
    for(const row of document.querySelectorAll('#full-export-history tr[data-export]'))row.classList.toggle('selected',row.dataset.export===job.id);
    controls();
  }
  async function open(jobId,original){
    const sequence=++x.detailLoad,job=original||await api('/api/jobs/'+encodeURIComponent(jobId));
    if(sequence!==x.detailLoad)return;
    if(job.kind!=='query-export')throw Error('Choose a retained query export.');
    x.selected=job;s.focusJob=job.id;try{localStorage.setItem(key('selected'),job.id);}catch{}
    renderDetail();progress(job);tab('exports');
    if(job.status==='RUNNING'){s.active=job.id;schedulePoll();}
  }
  async function downloadFile(job,file){
    let handle=null;
    if(window.showSaveFilePicker){try{handle=await window.showSaveFilePicker({suggestedName:file.name});}catch(error){if(error.name==='AbortError')return;throw error;}}
    else if(file.bytes>64*1024*1024)throw Error('This browser can save files up to 64 MiB. Use a browser with streaming file save, or copy the complete retained file from '+job.result.directory+'/'+file.name+'.');
    const response=await fetch('/api/query-exports/'+job.id+'/file?name='+encodeURIComponent(file.name),{headers:{'X-Analysis-Capability':capability},cache:'no-store'});
    if(!response.ok){const error=await response.json();throw Error(error.error||'Export download failed');}
    if(handle){const writable=await handle.createWritable();try{await response.body.pipeTo(writable);}catch(error){await writable.abort().catch(()=>{});throw error;}}
    else{const blob=await response.blob(),url=URL.createObjectURL(blob),anchor=node('a');anchor.href=url;anchor.download=file.name;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
    message('Saved '+file.name+' · '+bytes(file.bytes)+' · SHA-256 '+file.sha256);
  }
  async function refresh(){
    if(x.workspace!==s.data.workspace_id){x.workspace=s.data.workspace_id;x.restored=false;restoreOptions();}
    queryOptions();await history();
    if(!x.restored){
      x.restored=true;let selected;try{selected=localStorage.getItem(key('selected'));}catch{}
      if(selected&&/^[a-f0-9]{32}$/.test(selected)){
        const job=await api('/api/jobs/'+encodeURIComponent(selected));
        if(job.kind==='query-export'){x.selected=job;renderDetail();progress(job);}
      }
    }
    const running=s.data.jobs.find(job=>job.kind==='query-export'&&job.status==='RUNNING');
    if(running){const job=await api('/api/jobs/'+running.id);progress(job);}
    else if(x.active){const job=await api('/api/jobs/'+x.active.id);progress(job);}
    controls();
  }
  $('full-export-form').addEventListener('submit',event=>{event.preventDefault();act(begin);});
  $('full-export-choose').addEventListener('click',()=>{tab('analysis');$('saved-query').focus();});
  $('full-export-review-editor').addEventListener('click',()=>act(reviewEditor));
  $('full-export-from-result').addEventListener('click',()=>act(()=>review(s.result)));
  $('full-export-use-result').addEventListener('click',()=>act(()=>review(s.result)));
  $('full-export-query').addEventListener('change',()=>act(async()=>{const value=$('full-export-query').value;if(value)await review(value);else{x.review=null;renderReview();}}));
  $('full-export-reuse').addEventListener('click',()=>act(()=>review(x.selected.request.query_id)));
  $('full-export-cancel').addEventListener('click',()=>act(cancel));
  $('full-export-history-refresh').addEventListener('click',()=>act(()=>history(null,[])));
  $('full-export-history-next').addEventListener('click',()=>act(()=>history(x.history.next_before,[...x.pages,x.before])));
  $('full-export-history-prev').addEventListener('click',()=>act(()=>history(x.pages.at(-1),x.pages.slice(0,-1))));
  for(const field of options)$(field).addEventListener('input',rememberOptions);
  for(const input of document.querySelectorAll('[name="full-export-format"]'))input.addEventListener('change',rememberOptions);
  return {controls,refresh,open,progress,settled,queryReady,review};
})();
'''

"""Dependency-free customer data profile view, served by the original workspace."""
HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Data profiles · Stellar Forge</title><link rel="stylesheet" href="/profiles.css"><script src="/profiles.js" defer></script></head>
<body><header><div><p class="eyebrow">STELLAR FORGE / CUSTOMER DATA</p><h1>Data profiles</h1><p>Understand an acquired edition before using it.</p></div><div class="actions"><a id="workspace-link" href="/">Analysis workspace</a><button id="refresh">Refresh</button></div></header>
<div id="message" role="status" aria-live="polite">Connecting to the original analysis workspace.</div>
<section id="pending-panel" class="panel" hidden aria-label="Retained requests"><h2>Recover an interrupted request</h2><p id="pending-info"></p><div class="actions"><button id="retry-run" hidden>Retry original profile request</button><button id="retry-review" hidden>Retry original review save</button><button id="forget-pending">Forget retained browser requests</button></div></section>
<div class="layout"><aside><h2>Saved profiles</h2><div id="history"></div><button id="more-history" hidden>Earlier profiles</button></aside><main>
<section class="panel"><h2>Profile an imported edition</h2><p>All rows contribute to the statistics. Select the complete edition or specific columns; no purchase or view change is made.</p><div class="form-row"><label>Retained edition<select id="version"></select></label><button id="more-versions" hidden>Earlier editions</button></div><div id="version-info" class="facts"></div><details><summary>Columns and run settings</summary><fieldset><legend>Columns to include</legend><div class="actions"><button id="all-columns">Select all</button><button id="no-columns">Clear selection</button></div><div id="column-options" class="checks"></div></fieldset><div class="form-row"><label>Top values per column<input id="top-values" type="number" min="1" max="50" value="12"></label><label>Run deadline (seconds)<input id="timeout" type="number" min="1" max="86400" value="3600"></label></div></details><div class="actions"><button id="run" class="primary">Profile selected edition</button><button id="cancel" hidden>Cancel current profile</button><span id="progress"></span></div></section>
<section class="panel" id="profile-panel" hidden><div class="section-head"><div><p class="eyebrow">COMPLETE EDITION PROFILE</p><h2 id="profile-title"></h2></div><div class="actions"><button id="download-json">Export portable JSON</button><button id="download-html">Export readable report</button></div></div><div id="overview" class="metrics"></div><p class="hint">Null, empty text and whitespace-only text are separate. Numeric-looking text remains text. A top-value list is a frequency-ranked subset unless marked complete.</p><label>Find a column<input id="column-filter" type="search" placeholder="Name or original field"></label><div class="table-scroll"><table><thead><tr><th>Column</th><th>Null / rows</th><th>Empty text</th><th>Distinct non-null</th><th>Repeated rows</th><th>Storage classes</th><th></th></tr></thead><tbody id="summary"></tbody></table></div>
<section id="column-detail" hidden><h3 id="column-title"></h3><div id="column-facts" class="facts"></div><div class="table-scroll"><table><thead><tr><th>Value</th><th>Native type</th><th>Rows</th></tr></thead><tbody id="values"></tbody></table></div><p id="values-scope" class="hint"></p><details><summary>Use the complete value dictionary in the original SQL workspace</summary><pre id="frequency-sql"></pre><div class="form-row"><label>New saved-query name<input id="query-name" placeholder="inventory_categories" maxlength="64"></label><button id="save-frequency">Save frequency query</button></div></details><label>Column review note<textarea id="column-note" rows="3" maxlength="4000"></textarea></label><button id="keep-column-note">Keep in review draft</button></section>
<h3>Analyst review</h3><p id="review-version" class="hint"></p><label>Classification<select id="decision"><option value="unclassified">Unclassified</option><option value="usable">Usable for the intended analysis</option><option value="investigate">Investigate</option><option value="reference">Reference only</option></select></label><label>Review note<textarea id="note" rows="4" maxlength="16000" placeholder="Document the intended use, important fields, and observations."></textarea></label><div class="actions"><button id="save-review">Save review</button><span id="draft-state"></span></div><details><summary>Original source and calculation scope</summary><pre id="source"></pre></details></section>
<section class="panel"><h2>Compare edition profiles</h2><p>Compare counts, storage classes, ranges and value distributions. The original row-level Changes view remains available for keyed record differences.</p><div class="form-row"><label>Before<select id="before"></select></label><label>After<select id="after"></select></label><button id="compare">Compare profiles</button></div><div id="comparison" hidden><p id="comparison-summary"></p><div class="table-scroll"><table><thead><tr><th>Column</th><th>Status</th><th>Null change</th><th>Distinct change</th><th>Repeated-row change</th><th>Numeric range before → after</th></tr></thead><tbody id="comparison-rows"></tbody></table></div><button id="comparison-json">Export comparison JSON</button><details><summary>Compared source editions</summary><pre id="comparison-source"></pre></details></div></section>
</main></div><footer>Profiles and notes use the original local dataset database. Exported JSON reopens without the source service.</footer></body></html>'''

CSS = r'''
:root{font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#242424;background:#f3f3f3;color-scheme:light}*{box-sizing:border-box}body{margin:0}header{display:flex;justify-content:space-between;gap:24px;align-items:center;padding:24px 32px;background:#fff;border-bottom:1px solid #bbb}h1{font-size:28px;line-height:1.15;margin:5px 0 8px}h2{font-size:19px;margin:0 0 12px}h3{font-size:17px;margin:24px 0 10px}p{margin:8px 0 16px}.eyebrow{font-size:11px;letter-spacing:.12em;font-weight:650;margin:0;color:#555}.layout{display:grid;grid-template-columns:248px minmax(0,1fr);max-width:1550px;margin:auto}aside{padding:24px 18px;border-right:1px solid #ccc;min-width:0}main{min-width:0;padding:24px;display:grid;gap:20px;align-content:start}.panel{padding:24px;border:1px solid #c4c4c4;background:#fff;min-width:0}button,a,input,select,textarea{font:inherit}button,a{color:inherit}button{padding:8px 13px;background:#fff;border:1px solid #8d8d8d;border-radius:2px;cursor:pointer}button:hover:not(:disabled){background:#e9e9e9}button:disabled{opacity:.5;cursor:default}button.primary{background:#303030;color:white;border-color:#303030}a{padding:8px 0;text-underline-offset:3px}.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.form-row{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin:16px 0}.form-row>label{flex:1;min-width:180px}label{display:block;margin:10px 0;font-weight:550}input,select,textarea{display:block;width:100%;padding:9px;margin-top:6px;border:1px solid #999;border-radius:2px;background:#fff;color:#202020;font-weight:400}textarea{resize:vertical;min-height:65px}input:focus,select:focus,textarea:focus,button:focus-visible,a:focus-visible{outline:2px solid #222;outline-offset:2px}.hint,.muted{color:#606060;font-size:12px}#message{padding:12px 32px;background:#ececec;border-bottom:1px solid #c6c6c6;overflow-wrap:anywhere}#message.error{font-weight:600;border-left:5px solid #333}details{margin:15px 0}summary{cursor:pointer;font-weight:550}fieldset{border:1px solid #ccc;margin:14px 0;padding:14px}.checks{display:flex;flex-wrap:wrap;gap:10px;margin-top:10px}.checks label{font-size:13px;display:flex;align-items:center;gap:7px;margin:0;font-weight:400}.checks input{display:inline;width:auto;margin:0}.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:12px;overflow-wrap:anywhere;margin:12px 0}.facts div{background:#f6f6f6;padding:10px}.facts b{display:block;font-size:11px;letter-spacing:.025em;margin-bottom:4px}.table-scroll{overflow:auto;border:1px solid #ccc;margin:15px 0}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:10px;border-bottom:1px solid #d2d2d2;text-align:left;vertical-align:top;white-space:normal;overflow-wrap:anywhere;min-width:85px}th{background:#eee;font-weight:600}tr:last-child td{border-bottom:0}td button{font-size:12px;padding:5px 9px}.section-head{display:flex;justify-content:space-between;gap:16px;align-items:start;flex-wrap:wrap}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px}.metric{border:1px solid #ccc;padding:13px}.metric strong{display:block;font-size:24px}.metric span{font-size:12px;color:#555}pre{font:12px/1.5 ui-monospace,Consolas,monospace;background:#f2f2f2;padding:14px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:450px;overflow:auto}.history-item{padding:12px 0;border-bottom:1px solid #ccc}.history-item button{width:100%;text-align:left;margin-bottom:5px;overflow-wrap:anywhere}.history-item small{display:block;font-size:11px;overflow-wrap:anywhere}footer{padding:18px 32px;color:#666;border-top:1px solid #ccc;font-size:12px}[hidden]{display:none!important}#column-detail{border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:6px 0 18px}.code{font-family:ui-monospace,monospace}.delta{white-space:nowrap}#progress{font-size:12px;overflow-wrap:anywhere;flex:1}@media(max-width:850px){header{padding:20px;align-items:start}.layout{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid #ccc;padding:18px}#history{display:flex;gap:14px;overflow:auto}.history-item{min-width:205px;max-width:250px;border:0}main{padding:16px}.panel{padding:18px}}@media(max-width:500px){header{display:block}header>.actions{margin-top:16px}.panel{padding:15px}main{padding:12px}.form-row{display:block}.form-row>button{margin-top:8px}.metrics{grid-template-columns:1fr 1fr}#message{padding:12px 18px}.section-head>.actions{gap:7px}.section-head>.actions button{font-size:12px}footer{padding:18px}h1{font-size:25px}}
'''

JS = r'''"use strict";
const $=id=>document.getElementById(id);
if(location.hash.length>1){sessionStorage.setItem('sf-analysis-capability',location.hash.slice(1));history.replaceState(null,'',location.pathname);}
const capability=sessionStorage.getItem('sf-analysis-capability')||'';
$('workspace-link').href='/#'+capability;
const s={versions:[],profiles:[],versionNext:null,historyNext:null,document:null,column:null,notes:{},dirty:false,busy:false,active:null,comparison:null,workspaceId:null,pending:{run:null,review:null},pendingInvalid:false};
function node(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);return n;}
function cell(tr,text){const td=node('td',text);tr.append(td);return td;}
function action(label,fn){const b=node('button',label);b.addEventListener('click',()=>act(fn));return b;}
function message(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error);}
function short(value){return String(value||'').slice(0,12);}
function text(value){return value==null?'—':value.type+': '+(value.text===''&&value.type==='text'?'[empty]':value.text)+(value.truncated?'… [preview]':'');}
function fact(parent,label,value){const d=node('div');d.append(node('b',label),node('span',value??'—'));parent.append(d);}
function controls(){for(const id of ['run','refresh','more-versions','more-history','save-review','save-frequency','compare','download-json','download-html','comparison-json','retry-run','retry-review','forget-pending'])$(id).disabled=s.busy;$('run').disabled||=Boolean(s.active)||!s.versions.length||s.pendingInvalid;$('save-review').disabled||=s.pendingInvalid;$('compare').disabled||=!$('before').value||!$('after').value;$('cancel').hidden=!s.active;}
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'X-Analysis-Capability':capability,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data;}
function pendingKey(){if(!s.workspaceId)throw Error('Reconnect to the original workspace first.');return 'sf-profile-pending:'+s.workspaceId;}
function renderPending(){const run=s.pending.run,review=s.pending.review;$('pending-panel').hidden=!(run||review||s.pendingInvalid);$('retry-run').hidden=!run;$('retry-review').hidden=!review;$('pending-info').textContent=s.pendingInvalid?'The retained browser request could not be read. It has not been replaced. Use the workspace history before explicitly forgetting this local copy.':[(run?'Profile request '+run.body.id+' for edition '+short(run.body.version_id)+'.':''),(review?'Review save '+review.body.id+' for profile '+review.profile_id+'.':'')].filter(Boolean).join(' ')+' A reply was not confirmed. Retry sends the exact original ID and body; it does not create a new scan or review.';}
function storePending(value){sessionStorage.setItem(pendingKey(),JSON.stringify(value));s.pending=value;s.pendingInvalid=false;renderPending();}
function loadPending(){const raw=sessionStorage.getItem(pendingKey());if(!raw){s.pending={run:null,review:null};renderPending();return;}try{const value=JSON.parse(raw),id=/^[a-f0-9]{32}$/,sha=/^[a-f0-9]{64}$/;if(!value||typeof value!=='object'||Array.isArray(value)||value.run&&(!id.test(value.run.body?.id)||!sha.test(value.run.body?.version_id))||value.review&&(!id.test(value.review.profile_id)||!id.test(value.review.body?.id)||!sha.test(value.review.body?.profile_sha256)))throw Error('Invalid retained request');s.pending={run:value.run||null,review:value.review||null};s.pendingInvalid=false;}catch{s.pendingInvalid=true;}renderPending();}
function newRequestId(){return crypto.randomUUID().replaceAll('-','');}
async function submitPendingRun(){const pending=s.pending.run;if(!pending)throw Error('No retained profile request.');const job=await api('/api/start/profile',pending.body);storePending({...s.pending,run:null});s.dirty=false;await loadHistory();if(job.status==='RUNNING'){s.active=job.id;message('Original profile request accepted: '+job.id);poll();}else if(job.status==='COMPLETE'){await openProfile(job.id);$('progress').textContent='COMPLETE';message('Reopened the completed original profile '+short(job.id)+'.');}else{message('Original profile is '+job.status+(job.error?': '+job.error:''),job.status==='FAILED');}}
async function submitPendingReview(){const pending=s.pending.review;if(!pending)throw Error('No retained review request.');await api('/api/profiles/'+pending.profile_id+'/review',pending.body);storePending({...s.pending,review:null});s.dirty=false;await openProfile(pending.profile_id);message('Original review save confirmed in the dataset database.');}
async function restorePendingDraft(){const pending=s.pending.review;if(!pending||s.document)return;await openProfile(pending.profile_id);s.notes={...pending.body.column_notes};$('decision').value=pending.body.decision;$('note').value=pending.body.note;markDirty();$('draft-state').textContent='Retained review draft · retry its original save';}
async function act(fn){if(s.busy)return;s.busy=true;controls();try{await fn();}catch(e){message(e.message,true);}finally{s.busy=false;controls();}}
function markDirty(){s.dirty=true;$('draft-state').textContent='Unsaved review changes';}
function canLeave(){return !s.dirty||confirm('Discard the unsaved review draft?');}
function versionName(v){return (v.dataset?.name||v.dataset?.datasetId||v.dataset?.snapshot||'Imported edition')+' · '+v.row_count+' rows · '+short(v.version_id);}
async function loadVersions(more=false){const page=await api('/api/versions'+(more&&s.versionNext?'?before='+s.versionNext:''));s.versions=more?[...s.versions,...page.versions]:page.versions;s.versionNext=page.next_before;const old=$('version').value;const select=$('version');select.replaceChildren();for(const v of s.versions){const o=node('option',versionName(v));o.value=v.version_id;select.append(o);}if(s.versions.some(v=>v.version_id===old))select.value=old;$('more-versions').hidden=!s.versionNext;renderVersion();}
function renderVersion(){const v=s.versions.find(v=>v.version_id===$('version').value);$('version-info').replaceChildren();$('column-options').replaceChildren();if(!v){$('version-info').textContent='Import a retained dataset or API response in the analysis workspace first.';return;}fact($('version-info'),'Rows',v.row_count);fact($('version-info'),'Columns',v.column_types.length);fact($('version-info'),'Version',v.version_id);for(const c of v.column_types){const label=node('label'),input=node('input');input.type='checkbox';input.checked=true;input.value=c.column;label.append(input,document.createTextNode(c.column));$('column-options').append(label);}}
async function loadHistory(more=false){const page=await api('/api/profiles'+(more&&s.historyNext?'?before='+s.historyNext:''));s.profiles=more?[...s.profiles,...page.profiles]:page.profiles;s.historyNext=page.next_before;$('more-history').hidden=!s.historyNext;renderHistory();}
function renderHistory(){const box=$('history');box.replaceChildren();for(const p of s.profiles){const item=node('div');item.className='history-item';const b=action(short(p.version_id)+' · '+p.status,()=>openProfile(p.id));b.disabled=p.status!=='COMPLETE';item.append(b,node('small',p.created_at),node('small',short(p.id)+(p.error?' · '+p.error:'')));box.append(item);}if(!s.profiles.length)box.append(node('p','No profiles yet.'));for(const id of ['before','after']){const old=$(id).value;$(id).replaceChildren(node('option','Select a complete profile'));$(id).firstChild.value='';for(const p of s.profiles.filter(p=>p.status==='COMPLETE')){const o=node('option',short(p.version_id)+' · '+p.created_at);o.value=p.id;$(id).append(o);}if(s.profiles.some(p=>p.id===old))$(id).value=old;}s.active=s.profiles.find(p=>p.status==='RUNNING')?.id||null;controls();}
async function refresh(){if(!s.workspaceId){const state=await api('/api/state');s.workspaceId=state.workspace_id;loadPending();}await loadVersions();await loadHistory();await restorePendingDraft();if(s.active)poll();renderPending();message('Original customer workspace ready.');}
function metric(label,value){const d=node('div');d.className='metric';d.append(node('strong',value),node('span',label));$('overview').append(d);}
async function openProfile(id){if(!canLeave())return;s.document=await api('/api/profiles/'+id);s.column=null;s.notes={...(s.document.review?.column_notes||{})};s.dirty=false;$('draft-state').textContent='';$('column-detail').hidden=true;$('profile-panel').hidden=false;const p=s.document.profile;$('profile-title').textContent=(p.source.dataset?.name||'Retained edition')+' · '+short(p.source.version_id);$('overview').replaceChildren();metric('Rows inspected',p.row_count);metric('Columns',p.columns.length);metric('Columns with nulls',p.columns.filter(c=>c.null_rows>0).length);metric('Mixed native types',p.columns.filter(c=>Object.values(c.storage_classes).filter(v=>v>0).length>1).length);$('source').textContent=JSON.stringify({source:p.source,scope:p.scope,profile_sha256:p.sha256},null,2);$('decision').value=s.document.review?.decision||'unclassified';$('note').value=s.document.review?.note||'';$('review-version').textContent=s.document.review?'Saved revision '+s.document.review.revision+' · '+s.document.review.saved_at:'No saved review. Classification is an analyst note, not an acquisition or runtime control.';$('after').value=id;renderSummary();message('Opened complete profile '+short(id)+'.');}
function renderSummary(){if(!s.document)return;const term=$('column-filter').value.toLowerCase();$('summary').replaceChildren();for(const c of s.document.profile.columns.filter(c=>(c.column+' '+c.source_field).toLowerCase().includes(term))){const tr=node('tr');cell(tr,c.column);cell(tr,c.null_rows+' / '+c.rows);cell(tr,c.empty_text_rows);cell(tr,c.distinct_nonnull);cell(tr,c.duplicate_nonnull_rows);cell(tr,Object.entries(c.storage_classes).filter(([,v])=>v).map(([k,v])=>k+': '+v).join(', ')||'Empty edition');cell(tr).append(action('Inspect',()=>openColumn(c.column)));$('summary').append(tr);}}
function keepColumnNote(){if(s.column){s.notes[s.column]=$('column-note').value;}}
async function openColumn(name){keepColumnNote();s.column=name;const c=s.document.profile.columns.find(c=>c.column===name);$('column-detail').hidden=false;$('column-title').textContent=name;$('column-facts').replaceChildren();fact($('column-facts'),'Original field',c.source_field);fact($('column-facts'),'Original JSON types',c.original_json_types.join(', ')||'No rows');fact($('column-facts'),'Numeric minimum',text(c.numeric_min));fact($('column-facts'),'Numeric maximum',text(c.numeric_max));fact($('column-facts'),'Text minimum',text(c.text_min));fact($('column-facts'),'Text maximum',text(c.text_max));fact($('column-facts'),'Text length in characters',c.text_characters_min===null?'No text':c.text_characters_min+' → '+c.text_characters_max);fact($('column-facts'),'Whitespace-only rows',c.whitespace_text_rows);$('values').replaceChildren();for(const v of c.top_values){const tr=node('tr');const td=cell(tr,text(v.value));td.title=v.value.sha256||'';cell(tr,v.value.type);cell(tr,v.rows);$('values').append(tr);}$('values-scope').textContent=c.top_values_complete?'Every distinct native value is shown.':'Showing the '+c.top_values.length+' most frequent values out of '+c.distinct_including_null+'. Counts and ranges include every group.';$('column-note').value=s.notes[name]||'';const q=await api('/api/profiles/'+s.document.profile.id+'/frequency?column='+encodeURIComponent(name));$('frequency-sql').textContent=q.sql;}
async function poll(){const id=s.active;if(!id)return;try{const job=await api('/api/jobs/'+id),p=await api('/api/profiles/'+id+'/progress');$('progress').textContent=p.progress?'Column '+(p.progress.columns_complete||0)+' / '+(p.progress.columns_total||'?')+' · '+(p.progress.current_column||'Preparing'):job.status;if(job.status!=='RUNNING'){s.active=null;await loadHistory();$('progress').textContent=job.status;if(job.status==='COMPLETE')await openProfile(id);else message('Profile '+job.status+(job.error?': '+job.error:''),job.status==='FAILED');return;}}catch(e){message(e.message,true);return;}setTimeout(()=>{if(s.active===id)poll();},1200);}
async function download(path,name){const r=await fetch(path,{headers:{'X-Analysis-Capability':capability},cache:'no-store'});if(!r.ok){const e=await r.json();throw Error(e.error||'Export failed');}const blob=await r.blob(),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function saveJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'}));const a=node('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
for(const id of ['before','after'])$(id).addEventListener('change',controls);
$('refresh').addEventListener('click',()=>act(refresh));$('version').addEventListener('change',renderVersion);$('more-versions').addEventListener('click',()=>act(()=>loadVersions(true)));$('more-history').addEventListener('click',()=>act(()=>loadHistory(true)));$('all-columns').addEventListener('click',()=>{for(const c of $('column-options').querySelectorAll('input'))c.checked=true;});$('no-columns').addEventListener('click',()=>{for(const c of $('column-options').querySelectorAll('input'))c.checked=false;});
$('run').addEventListener('click',()=>act(async()=>{if(!canLeave())return;const all=[...$('column-options').querySelectorAll('input')],columns=all.filter(c=>c.checked).map(c=>c.value);if(!columns.length)throw Error('Select at least one column.');const spec={version_id:$('version').value,columns:columns.length===all.length?null:columns,top_values:Number($('top-values').value),timeout:Number($('timeout').value)};if(s.pending.run){const {id,...original}=s.pending.run.body;if(JSON.stringify(original)!==JSON.stringify(spec))throw Error('Resolve the retained profile request before starting a different selection.');}else storePending({...s.pending,run:{body:{id:newRequestId(),...spec}}});await submitPendingRun();}));
$('cancel').addEventListener('click',async()=>{try{if(s.active){const r=await api('/api/profiles/'+s.active+'/cancel',{});message(r.requested?'Cancellation requested for this profile.':'Profile is already '+r.status);}}catch(e){message(e.message,true);}});
$('column-filter').addEventListener('input',renderSummary);$('note').addEventListener('input',markDirty);$('decision').addEventListener('change',markDirty);$('column-note').addEventListener('input',markDirty);$('keep-column-note').addEventListener('click',()=>{keepColumnNote();markDirty();message('Column note retained in the review draft. Save review to persist it.');});
$('save-review').addEventListener('click',()=>act(async()=>{keepColumnNote();const p=s.document.profile,spec={profile_sha256:p.sha256,decision:$('decision').value,note:$('note').value,column_notes:JSON.parse(JSON.stringify(s.notes))};if(s.pending.review){const original=s.pending.review.body;if(s.pending.review.profile_id!==p.id||original.profile_sha256!==spec.profile_sha256||original.decision!==spec.decision||original.note!==spec.note||JSON.stringify(original.column_notes)!==JSON.stringify(spec.column_notes))throw Error('Resolve the retained review save before replacing its edited notes.');}else storePending({...s.pending,review:{profile_id:p.id,body:{id:newRequestId(),expected_revision:s.document.review?.revision||0,...spec}}});await submitPendingReview();}));
$('save-frequency').addEventListener('click',()=>act(async()=>{const q=await api('/api/profiles/'+s.document.profile.id+'/frequency-query',{column:s.column,name:$('query-name').value.trim(),expected_revision:0});message('Saved '+q.name+' revision '+q.revision+'. Open it in the analysis workspace for full SQL export.');}));
for(const format of ['json','html'])$('download-'+format).addEventListener('click',()=>act(async()=>{if(s.dirty)throw Error('Save or discard review changes before exporting.');await download('/api/profiles/'+s.document.profile.id+'/export?format='+format+'&expected_sha256='+s.document.sha256,'data-profile-'+short(s.document.profile.id)+'.'+format);}));
$('compare').addEventListener('click',()=>act(async()=>{s.comparison=await api('/api/profile-compare?before='+$('before').value+'&after='+$('after').value);const c=s.comparison;$('comparison').hidden=false;$('comparison-summary').textContent='Imported row change: '+(c.row_delta>0?'+':'')+c.row_delta+'. '+c.columns.filter(v=>v.status!=='unchanged').length+' of '+c.columns.length+' columns differ.';$('comparison-rows').replaceChildren();const delta=v=>v==null?'—':(v>0?'+':'')+v;for(const col of c.columns){const tr=node('tr');cell(tr,col.column);cell(tr,col.status);cell(tr,delta(col.deltas?.null_rows));cell(tr,delta(col.deltas?.distinct_nonnull));cell(tr,delta(col.deltas?.duplicate_nonnull_rows));cell(tr,text(col.before?.numeric_min)+' … '+text(col.before?.numeric_max)+' → '+text(col.after?.numeric_min)+' … '+text(col.after?.numeric_max));$('comparison-rows').append(tr);}$('comparison-source').textContent=JSON.stringify({before:c.before_source,after:c.after_source,basis:c.basis},null,2);message('Compared the complete retained profiles.');}));
$('comparison-json').addEventListener('click',()=>saveJSON(s.comparison,'data-profile-comparison.json'));
window.addEventListener('beforeunload',e=>{if(s.dirty||s.pending.run||s.pending.review||s.pendingInvalid){e.preventDefault();e.returnValue='';}});
$('retry-run').addEventListener('click',()=>act(submitPendingRun));
$('retry-review').addEventListener('click',()=>act(submitPendingReview));
$('forget-pending').addEventListener('click',()=>act(async()=>{if(!confirm('Forget only these retained browser requests? A run or review may already have been accepted. Its saved workspace history will remain.'))return;storePending({run:null,review:null});message('Local pending requests forgotten explicitly. Original saved operations remain in the workspace.');}));
act(refresh);
